UPDATE outbox_events SET status = 'PENDING', retry_count = retry_count + 1, next_retry_at = DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 5 SECOND),
 claimed_by = NULL, claimed_until = NULL, last_error = #{error}
WHERE id = #{id} AND status = 'PROCESSING' AND claimed_by = #{worker} AND claimed_until > UTC_TIMESTAMP(6)
